import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.aJDz64y9.js";const m=JSON.parse('{"title":"Общий каркас: шесть фаз, роли и «жар»","description":"","frontmatter":{},"headers":[],"relativePath":"crime/framework.md","filePath":"crime/framework.md","lastUpdated":1794540927000}'),o={name:"crime/framework.md"};function h(i,t,l,n,s,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="общии-каркас-шесть-фаз-роли-и-«жар»" tabindex="-1">Общий каркас: шесть фаз, роли и «жар» <a class="header-anchor" href="#общии-каркас-шесть-фаз-роли-и-«жар»" aria-label="Permalink to &quot;Общий каркас: шесть фаз, роли и «жар»&quot;">​</a></h1><p>Все три активности собраны из одних и тех же шести фаз. Инструменты, роли и последствия общие, различается только содержимое.</p><table tabindex="0"><thead><tr><th>Фаза</th><th>Что делает игрок</th><th>Главное решение</th><th>Что идёт не так</th></tr></thead><tbody><tr><td>1. Наводка</td><td>Узнаёт, где и что брать: покупает сведения, сам наблюдает за объектом, берёт заказ</td><td>Какой объект и в какое время</td><td>Наводка устарела или продана двум командам</td></tr><tr><td>2. Подготовка</td><td>Собирает инструмент, транспорт, людей, маски</td><td>Тихий план или громкий, сколько людей брать</td><td>Нужного инструмента нет, план меняется на ходу</td></tr><tr><td>3. Проникновение</td><td>Вскрывает замок, окно, щиток, машину</td><td>Какой вход выбрать, тратить ли дорогой инструмент</td><td>Шум, сломанная отмычка, сработавшая сигнализация</td></tr><tr><td>4. Добыча</td><td>Обыскивает, хватает, выносит. Место в сумке и багажнике ограничено</td><td>Что брать и когда остановиться</td><td>Проснулись жильцы, вернулся владелец, приехал патруль</td></tr><tr><td>5. Отход</td><td>Уходит от полиции и свидетелей, прячет добычу</td><td>Маршрут, смена машины, где отлежаться</td><td>Погоня, досмотр, метка в товаре</td></tr><tr><td>6. Сбыт</td><td>Продаёт скупщику, механику, под заказ</td><td>Сразу и дёшево или позже и дороже</td><td>Товар «палёный», точка сбыта под наблюдением</td></tr></tbody></table><h2 id="роли" tabindex="-1">Роли <a class="header-anchor" href="#роли" aria-label="Permalink to &quot;Роли&quot;">​</a></h2><p>Роль — это навык, который растёт от практики, а не класс персонажа. Рекомендация: до мастера качается одна ветка, остальные — до среднего уровня. Одиночка закрывает первую ступень сам, на верхних нужен напарник с другим навыком.</p><table tabindex="0"><thead><tr><th>Роль</th><th>Что делает</th><th>Где незаменим</th></tr></thead><tbody><tr><td>Взломщик</td><td>Замки дверей, шкафов, сейфов и машин</td><td>Дома второй и третьей ступени, сейфы</td></tr><tr><td>Технарь</td><td>Сигнализация, щитки, камеры, жучки, глушилка</td><td>Магазины с охранной системой, дорогие машины</td></tr><tr><td>Водитель</td><td>Ждёт с заведённой машиной, уводит погоню, везёт крупный груз</td><td>Любой отход с габаритной добычей</td></tr><tr><td>Наблюдатель</td><td>Стоит снаружи, слушает полицейскую волну, предупреждает команду</td><td>Кражи, где внутри не видно улицы</td></tr><tr><td>Силовик</td><td>Держит под контролем продавца и посетителей</td><td>Налёт на открытый магазин</td></tr></tbody></table><h2 id="«жар»" tabindex="-1">«Жар» <a class="header-anchor" href="#«жар»" aria-label="Permalink to &quot;«Жар»&quot;">​</a></h2><p>«Жар» наказывает повторение, а не игрока: он привязан к району и к вещи, поэтому кулдауны на персонажа почти не нужны.</p><ul><li><strong>Жар района.</strong> Каждое преступление на несколько часов повышает тревожность района: патрулей больше, вызов уходит быстрее, жильцы чаще дома, на полках меньше дорогого. Команды вынуждены переезжать по карте, а фарм одной точки перестаёт окупаться.</li><li><strong>Палёность вещи.</strong> Краденый предмет помнит, откуда и когда украден. Свежий товар NPC-скупщик берёт с большой скидкой, очень свежий не берёт совсем. Вещь остывает за 1–3 реальных дня или после «чистки» у игрока-специалиста. Палёная вещь, найденная при обыске, привязывает человека к конкретному делу.</li></ul>',9)])])}const p=d(o,[["render",h]]);export{m as __pageData,p as default};
